GFNBounds.Doubling.Stat.tsum_lam_congr_a.type:
∀ {S : GFNBounds.Doubling.Setting} (L : GFNBounds.Doubling.Stat S none) {F : ↥(MeasureTheory.Lp ℝ 2 L.mu)}
  {g : GFNBounds.Doubling.St → ℝ},
  ↑↑F =ᵐ[L.mu] g → ∑' (x : GFNBounds.Doubling.St), L.lam x * ↑↑F x = ∑' (x : GFNBounds.Doubling.St), L.lam x * g x

GFNBounds.Doubling.Stat.mk.inj.type:
∀ {S : GFNBounds.Doubling.Setting} {cap : Option ℕ} {lam : GFNBounds.Doubling.St → ℝ}
  {nonneg : ∀ (x : GFNBounds.Doubling.St), 0 ≤ lam x}
  {pos : ∀ ⦃x : GFNBounds.Doubling.St⦄, GFNBounds.Doubling.OnChain cap x → 0 < lam x}
  {vanish : ∀ ⦃x : GFNBounds.Doubling.St⦄, ¬GFNBounds.Doubling.OnChain cap x → lam x = 0} {summable : Summable lam}
  {total : ∑' (x : GFNBounds.Doubling.St), lam x = 1}
  {inv :
    ∀ (f : GFNBounds.Doubling.St → ℝ),
      (∃ C, ∀ (x : GFNBounds.Doubling.St), |f x| ≤ C) →
        ∑' (x : GFNBounds.Doubling.St), lam x * GFNBounds.Doubling.pstar S cap f x =
          ∑' (x : GFNBounds.Doubling.St), lam x * f x}
  {lam_1 : GFNBounds.Doubling.St → ℝ} {nonneg_1 : ∀ (x : GFNBounds.Doubling.St), 0 ≤ lam_1 x}
  {pos_1 : ∀ ⦃x : GFNBounds.Doubling.St⦄, GFNBounds.Doubling.OnChain cap x → 0 < lam_1 x}
  {vanish_1 : ∀ ⦃x : GFNBounds.Doubling.St⦄, ¬GFNBounds.Doubling.OnChain cap x → lam_1 x = 0}
  {summable_1 : Summable lam_1} {total_1 : ∑' (x : GFNBounds.Doubling.St), lam_1 x = 1}
  {inv_1 :
    ∀ (f : GFNBounds.Doubling.St → ℝ),
      (∃ C, ∀ (x : GFNBounds.Doubling.St), |f x| ≤ C) →
        ∑' (x : GFNBounds.Doubling.St), lam_1 x * GFNBounds.Doubling.pstar S cap f x =
          ∑' (x : GFNBounds.Doubling.St), lam_1 x * f x},
  { lam := lam, nonneg := nonneg, pos := pos, vanish := vanish, summable := summable, total := total, inv := inv } =
      { lam := lam_1, nonneg := nonneg_1, pos := pos_1, vanish := vanish_1, summable := summable_1, total := total_1,
        inv := inv_1 } →
    lam = lam_1

GFNBounds.Doubling.Stat.coeFn_defect_toL.type:
∀ {S : GFNBounds.Doubling.Setting} (L : GFNBounds.Doubling.Stat S none) {f : GFNBounds.Doubling.St → ℝ}
  (hf : MeasureTheory.MemLp f 2 L.mu),
  ↑↑(L.defect (MeasureTheory.MemLp.toLp f hf)) =ᵐ[L.mu] fun x => f x - GFNBounds.Doubling.pstar S none f x

GFNBounds.Doubling.St.doc:
The states of the doubling graph `eq:counterexample_graph`.

`lad 0` **is** the source `s₀` (see `St.src`); `lad j` for `j ≥ 1` is the ladder state `j`;
`sink` is `s_f`.

GFNBounds.Doubling.Setting.mk.inj.type:
∀ {d : ℕ} {d_pos : 1 ≤ d} {eps : ℕ → ℝ} {eps_pos : ∀ ⦃j : ℕ⦄, 1 ≤ j → 0 < eps j} {epsMax : ℝ}
  {eps_le : ∀ ⦃j : ℕ⦄, 1 ≤ j → eps j ≤ epsMax} {epsMax_lt_one : epsMax < 1} {row : ℕ → ℝ}
  {row_nonneg : ∀ (j : ℕ), 0 ≤ row j} {row_supp : ∀ ⦃j : ℕ⦄, row j ≠ 0 → 1 ≤ j ∧ j ≤ d}
  {row_sum : ∑ j ∈ Finset.Icc 1 d, row j = 1} {d_1 : ℕ} {d_pos_1 : 1 ≤ d_1} {eps_1 : ℕ → ℝ}
  {eps_pos_1 : ∀ ⦃j : ℕ⦄, 1 ≤ j → 0 < eps_1 j} {epsMax_1 : ℝ} {eps_le_1 : ∀ ⦃j : ℕ⦄, 1 ≤ j → eps_1 j ≤ epsMax_1}
  {epsMax_lt_one_1 : epsMax_1 < 1} {row_1 : ℕ → ℝ} {row_nonneg_1 : ∀ (j : ℕ), 0 ≤ row_1 j}
  {row_supp_1 : ∀ ⦃j : ℕ⦄, row_1 j ≠ 0 → 1 ≤ j ∧ j ≤ d_1} {row_sum_1 : ∑ j ∈ Finset.Icc 1 d_1, row_1 j = 1},
  { d := d, d_pos := d_pos, eps := eps, eps_pos := eps_pos, epsMax := epsMax, eps_le := eps_le,
        epsMax_lt_one := epsMax_lt_one, row := row, row_nonneg := row_nonneg, row_supp := row_supp,
        row_sum := row_sum } =
      { d := d_1, d_pos := d_pos_1, eps := eps_1, eps_pos := eps_pos_1, epsMax := epsMax_1, eps_le := eps_le_1,
        epsMax_lt_one := epsMax_lt_one_1, row := row_1, row_nonneg := row_nonneg_1, row_supp := row_supp_1,
        row_sum := row_sum_1 } →
    d = d_1 ∧ eps = eps_1 ∧ epsMax = epsMax_1 ∧ row = row_1

